import { test, expect } from '@playwright/test';

test.describe('Notification Filtering', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should display info notifications when filtered by type', async ({ page }) => {
    await page.getByRole('button', { name: /filter/i }).click();
    await page.getByLabel('Notification Type').selectOption('info');
    await page.getByRole('button', { name: /apply/i }).click();

    const notifications = await page.getByRole('list', { name: /notifications/i }).locator('li');
    for (let i = 0; i < await notifications.count(); i++) {
      const notificationType = await notifications.nth(i).getByText(/type:/i).innerText();
      expect(notificationType).toContain('info');
    }
  });

  test('should display warning notifications when filtered by type', async ({ page }) => {
    await page.getByRole('button', { name: /filter/i }).click();
    await page.getByLabel('Notification Type').selectOption('warning');
    await page.getByRole('button', { name: /apply/i }).click();

    const notifications = await page.getByRole('list', { name: /notifications/i }).locator('li');
    for (let i = 0; i < await notifications.count(); i++) {
      const notificationType = await notifications.nth(i).getByText(/type:/i).innerText();
      expect(notificationType).toContain('warning');
    }
  });
});
